#!/bin/bash
dnf update -y
dnf install -y nodejs
mkdir -p /opt/app
echo "" | base64 -d > /opt/app/app.js
echo "ewogICAgIm5hbWUiOiAidmlld2VyLWFwcCIsCiAgICAidmVyc2lvbiI6ICIxLjAuMCIsCiAgICAibWFpbiI6ICJhcHAuanMiLAogICAgImRlcGVuZGVuY2llcyI6IHsKICAgICAgICAiZXhwcmVzcyI6ICJeNC4xOS4yIiwKICAgICAgICAiQGF3cy1zZGsvY2xpZW50LXMzIjogIl4zLjYwMC4wIgogICAgfQp9Cg==" | base64 -d > /opt/app/package.json
cd /opt/app
npm install --omit=dev

cat > /etc/systemd/system/viewer.service << 'SERVICE'
[Unit]
Description=Viewer App
After=network.target

[Service]
Environment=BUCKET_NAME=itmo-544-jimmy.wong-fileshare
Environment=AWS_REGION=us-east-2
Environment=PORT=3000
WorkingDirectory=/opt/app
ExecStart=/usr/bin/node	/opt/app/app.js
Restart=always
User=ec2-user

[Install]
WantedBy=multi-user.target
SERVICE

chown -R ec2-user:ec2-user /opt/app
systemctl daemon-reload
systemctl enable viewer.service
systemctl start viewer.service
